 uni constant uuid := '6a79211e-6e85-4d95-be24-976edb26ba58';
 campus constant uuid := '1d60dcae-760d-4de7-8443-6a870d9bbe1a';
 actor constant uuid := 'd34f89d0-aa39-4a92-b52f-a16af84a0b1f';
 key text := 'map2:'||(data->>'sourceSha256');
 p jsonb; expected integer; actual integer; protected_before jsonb; protected_after jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended('release-map:'||campus::text,0));
 if not exists(select 1 from public.institution_campuses c where c.id=campus and c.institution_id=uni and c.slug='ugbowo') then raise exception 'MAP2_CAMPUS_SCOPE';end if;
 if exists(select 1 from app_private.map_imports i where i.campus_id=campus and i.request_key=key and i.status='COMPLETE') then return;end if;
 if (select count(*) from public.campus_places where campus_id=campus)<>97 then raise exception 'MAP2_DIRECTORY_BASELINE_CHANGED';end if;
 select jsonb_build_object(
  'osm',(select md5(string_agg((to_jsonb(c)-'search_aliases'-'updated_at')::text,',' order by id)) from public.campus_places c where source_provider='OSM'),
  'others',(select md5(string_agg(to_jsonb(c)::text,',' order by id)) from public.campus_places c where campus_id is distinct from campus),
  'paths',(select md5(string_agg(to_jsonb(c)::text,',' order by id)) from public.campus_paths c),
  'entrances',(select md5(string_agg(to_jsonb(c)::text,',' order by id)) from public.campus_entrances c),
  'features',(select md5(string_agg(to_jsonb(c)::text,',' order by id)) from public.campus_map_features c),
  'campuses',(select md5(string_agg((to_jsonb(c)-'map_revision')::text,',' order by id)) from public.institution_campuses c)
 ) into protected_before;
 perform set_config('app.map_actor',actor::text,true);
 for p in select value from jsonb_array_elements(data->'patches') loop
  if p->>'action'<>'insert' and not exists(
   select 1 from public.campus_places c where c.id=(p->>'id')::uuid and c.campus_id=campus and c.university_id=uni
   and c.name=p->'before'->>'name' and c.latitude=(p->'before'->>'latitude')::numeric and c.longitude=(p->'before'->>'longitude')::numeric
   and c.source_provider=p->'before'->>'source_provider' and c.verified_at is not distinct from (p->'before'->>'verified_at')::timestamptz
  ) then raise exception 'MAP2_PLACE_BASELINE_CHANGED %',p->>'name';end if;
  if p->>'action'='insert' then
   if exists(select 1 from public.campus_places where id=(p->>'id')::uuid) then raise exception 'MAP2_ID_COLLISION';end if;
   insert into public.campus_places(id,university_id,campus_id,name,category,description,latitude,longitude,geom,search_aliases,status,source_provider,source_feature_id,confidence,verified_at)
   values((p->>'id')::uuid,uni,campus,p->>'name',p->>'category',p->>'description',(p->>'latitude')::numeric,(p->>'longitude')::numeric,
     public.ST_SetSRID(public.ST_MakePoint((p->>'longitude')::float8,(p->>'latitude')::float8),4326),array(select jsonb_array_elements_text(p->'search_aliases')),
     'PUBLISHED','KAMPUSONE','map2/'||substr(data->>'sourceSha256',1,12)||'/'||(p->>'id'),0.55,null);
  elsif p->>'action'='update' then
   update public.campus_places set latitude=(p->>'latitude')::numeric,longitude=(p->>'longitude')::numeric,
     search_aliases=array(select jsonb_array_elements_text(p->'search_aliases')),verified_at=null,confidence=0.55,
     source_feature_id='map2/'||substr(data->>'sourceSha256',1,12)||'/'||(p->>'id'),source_url=null,updated_at=now()
   where id=(p->>'id')::uuid and campus_id=campus and university_id=uni and source_provider='KAMPUSONE';
  else
   update public.campus_places set search_aliases=array(select jsonb_array_elements_text(p->'search_aliases')),updated_at=now()
   where id=(p->>'id')::uuid and campus_id=campus and university_id=uni;
  end if;
 end loop;
 for p in select value from jsonb_array_elements(data->'patches') where value->>'action'='insert' and value->>'parentId' is not null loop
  update public.campus_places set parent_place_id=(p->>'parentId')::uuid where id=(p->>'id')::uuid and campus_id=campus and university_id=uni;
 end loop;
 expected=(data->'counts'->>'directoryPlaces')::integer;
 select count(*) into actual from public.campus_places where campus_id=campus and university_id=uni;
 if actual<>expected then raise exception 'MAP2_COUNT_MISMATCH';end if;
 select jsonb_build_object(
  'osm',(select md5(string_agg((to_jsonb(c)-'search_aliases'-'updated_at')::text,',' order by id)) from public.campus_places c where source_provider='OSM'),
  'others',(select md5(string_agg(to_jsonb(c)::text,',' order by id)) from public.campus_places c where campus_id is distinct from campus),
  'paths',(select md5(string_agg(to_jsonb(c)::text,',' order by id)) from public.campus_paths c),
  'entrances',(select md5(string_agg(to_jsonb(c)::text,',' order by id)) from public.campus_entrances c),
  'features',(select md5(string_agg(to_jsonb(c)::text,',' order by id)) from public.campus_map_features c),
  'campuses',(select md5(string_agg((to_jsonb(c)-'map_revision')::text,',' order by id)) from public.institution_campuses c)
 ) into protected_after;
 if protected_before is distinct from protected_after then raise exception 'MAP2_PROTECTED_GEOMETRY_OR_SCOPE_CHANGED';end if;
 update public.institution_campuses set map_revision=map_revision+1 where id=campus and institution_id=uni;
 insert into app_private.map_imports(institution_id,campus_id,actor_user_id,source_provider,status,request_key,diagnostics,completed_at)
 values(uni,campus,actor,'KAMPUSONE','COMPLETE',key,jsonb_build_object('sourceSha256',data->>'sourceSha256','counts',data->'counts','accuracy','Approximate screenshot-derived points; no entrance survey.','preservation',protected_after),now());
 insert into app_private.audit_events(actor_user_id,university_id,action,target_type,target_id,outcome,metadata)
 values(actor,uni,'maps.screenshot-review.imported','map_import',key,'succeeded',data->'counts');
end $import$;
commit;
